struct Person {
    long id{}; std::string name; int age{};
    void insert(soci::session& sql) const {
        sql << "insert into person(name, age) values(:n, :a)", soci::use(name), soci::use(age);
    }
    static Person load(soci::session& sql, long id) {
        Person p; p.id = id;
        sql << "select name, age from person where id = :id", soci::use(id),
            soci::into(p.name), soci::into(p.age);
        return p;
    }
};
